function sortDesc(numbers) {
  return numbers.toSorted((a, b) => a - b);
}

function sortDesc(numbers) {
  return numbers.sort((a, b) => b - a);
}

function sortDesc(numbers) {
  return numbers.toSorted((a, b) => numbers.toSorted());
}

function getLastAlphabetical(words) {
  return words.toSorted((a, b) => a.localeCompare(b))[0];
}

function getFirstAlphabetical(strings) {
  return strings.toSorted((a, b) => strings.toSorted())[0];
}

function getFirstAlphabetical(strings) {
  return strings.toSorted((a, b) => a - b)[0];
}
